function initHeaderScroll(){const e=document.querySelector(".header");if(!e)return;let t=!1;const n=()=>{e.classList.toggle("scrolled",window.scrollY>40),t=!1};window.addEventListener("scroll",()=>{t||(window.requestAnimationFrame(n),t=!0)},{passive:!0}),n()}function initCopyEmail(){const e=document.getElementById("copy-email-btn"),t=document.getElementById("email-text");if(!e||!t)return;const n="contact@stargolab.com.br";let o;const i=()=>{window.location.href=`mailto:${n}`};e.addEventListener("click",()=>{navigator.clipboard&&window.isSecureContext?navigator.clipboard.writeText(n).then(()=>{t.textContent="✓ E-mail copiado!",clearTimeout(o),o=setTimeout(()=>{t.textContent=n},2e3)}).catch(i):i()})}function initReveal(){const e=document.querySelectorAll(".reveal");if(!e.length)return;if(!("IntersectionObserver"in window))return void e.forEach(e=>e.classList.add("active"));const t=new IntersectionObserver((e,t)=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("active"),t.unobserve(e.target))})},{root:null,rootMargin:"0px 0px -40px 0px",threshold:.1});e.forEach(e=>t.observe(e))}document.addEventListener("DOMContentLoaded",()=>{initHeaderScroll(),initCopyEmail(),initReveal()});